(self.webpackChunkvuepress_blog=self.webpackChunkvuepress_blog||[]).push([[9602],{2247:(s,n,a)=>{"use strict";a.r(n),a.d(n,{data:()=>t});const t={key:"v-00439f8c",path:"/pages/e2e-testing/Cypress/",title:"",lang:"zh-CN",frontmatter:{sideBar:"true;"},excerpt:"",headers:[{level:2,title:"Cypress 开发笔记",slug:"cypress-开发笔记",children:[]}],filePathRelative:"pages/e2e-testing/Cypress/README.md",git:{updatedTime:1776756909e3,contributors:[{name:"COOKIES-LGL",email:"1344714332@qq.com",commits:4}]}}},6717:(s,n,a)=>{"use strict";a.r(n),a.d(n,{default:()=>e});const t=(0,a(6252).uE)('<h2 id="cypress-开发笔记"><a class="header-anchor" href="#cypress-开发笔记">#</a> Cypress 开发笔记</h2><p>Cypress 的主要特点包括：</p><ul><li><code>可视化测试运行器</code>：Cypress 提供了一个可视化测试运行器，用于实时查看测试用例的执行情况、断言结果和 DOM 状态。这使得测试过程更直观、易于调试和故障排查。</li><li><code>自动等待机制</code>：Cypress 会自动等待页面上的各种操作完成，无需手动添加显式的等待时间。它会等待 XHR、异步操作、动画效果等自动完成，从而提高测试的稳定性和可靠性。</li><li><code>强大的选择器</code>：Cypress 支持强大的 DOM 元素选择器，包括 CSS 选择器和自定义选择器，使得测试用例能够轻松定位 DOM 元素和与之交互。</li><li><code>易于编写和理解的语法</code>：Cypress 使用简洁的语法，易于编写和理解。它提供了丰富的 API，用于模拟用户行为、进行断言、处理网络请求等，使得测试用例的编写变得简单而富有表达力。</li><li><code>内置的 Mock 和 Stub 功能</code>：Cypress 提供了内置的 Mock 和 Stub 功能，可以轻松地模拟和篡改服务器响应、网络请求等，方便进行集成测试和单元测试。</li><li><code>跨浏览器支持</code>：Cypress 支持多种常见的浏览器，包括 Chrome、Firefox、Edge 等，使得开发人员能够在不同的浏览器环境中运行和验证测试用例。</li></ul><h4 id="安装"><a class="header-anchor" href="#安装">#</a> 安装</h4><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code><span class="token function">npm</span> <span class="token function">install</span> cypress --save-dev\n\n<span class="token comment"># |-- cypress.json    // 配置文件</span>\n<span class="token comment"># |-- cypress</span>\n<span class="token comment">#     -- fixtures     // 用于存放自定义的json文件</span>\n<span class="token comment">#     -- integration  // 测试代码</span>\n<span class="token comment">#         -- examples  // 示例代码</span>\n<span class="token comment">#     -- plugins       // 自定义指令时，与support文件夹组合使用</span>\n<span class="token comment">#         -- index.js</span>\n<span class="token comment">#     -- support</span>\n<span class="token comment">#         -- commands.js</span>\n<span class="token comment">#         -- index.js</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h4 id="cypress-提供的不同-command"><a class="header-anchor" href="#cypress-提供的不同-command">#</a> Cypress 提供的不同 Command</h4><ol><li>beforeEach：在每个测试 function 都会执行</li><li>visit：顾名思义，就是访问远程 URL，跟 cypress.json 文件中的 baseURL 组合使用；</li><li>get：通过 selectors 或者别名，获取一个或者多个 Dom 元素</li><li>contains：获取包含指定文本的 DOM 元素</li><li>type：在 DOM 元素中键入的内容</li><li>click：单击操作</li><li>location：获取 window.location 的内容，可用参数有：host、port、hostname、href、pathname 等</li><li>wrap 方法可以将非 Cypress 对象包装成 Cypress 对象，使其能够使用 Cypress 命令链</li><li>cy.session() 方法可以通过缓存登录状态，避免每次测试都进行完整的登录流程。</li></ol><h4 id="关于-cypress-json"><a class="header-anchor" href="#关于-cypress-json">#</a> 关于 cypress.json</h4><table><thead><tr><th>选项</th><th>默认值</th><th>解释</th></tr></thead><tbody><tr><td>baseUrl</td><td>null</td><td>命令 cy.visit()或 cy.request()的前缀 URL</td></tr><tr><td>env</td><td>{}</td><td>可设置任何的配置项，通过 Cypress.env 调用</td></tr><tr><td>numTestsKeptInMemory</td><td>50</td><td>快照和命令数据在内存中保存的测试数</td></tr><tr><td>trashAssetsBeforeRuns</td><td>true</td><td>cypress run 运行时清空 screenshotsFolder 和 videosFolder</td></tr><tr><td>videosFolder</td><td>cypress/videos</td><td>视频文件保存的路径</td></tr><tr><td>screenshotsFolder</td><td>cypress/screenshots</td><td>快照文件保存的路径</td></tr><tr><td>reporter</td><td>spec</td><td>测试报告格式</td></tr><tr><td>reporterOptions</td><td>{}</td><td>测试报告参数</td></tr></tbody></table><h4 id="within"><a class="header-anchor" href="#within">#</a> within</h4><p>wrap() 方法可以将非 Cypress 对象包装成 Cypress 对象，使其能够使用 Cypress 命令链, 但是后续的选择和操作都是基于全局的的，而不是这个对象内部。 如果需要限制在对象内部可以使用 within 方法。</p><div class="language-javascript ext-js line-numbers-mode"><pre class="language-javascript"><code>cy<span class="token punctuation">.</span><span class="token function">wrap</span><span class="token punctuation">(</span>target<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">within</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>\n  cy<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;button &gt; span&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">contains</span><span class="token punctuation">(</span><span class="token string">&quot;Ok&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">should</span><span class="token punctuation">(</span><span class="token string">&quot;be.visible&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">click</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>',12),e={render:function(s,n){return t}}}}]);